<?php if (!defined('ABSPATH')) exit; $bid=(int)$bolao->id; if(isset($_POST['rsb_add_game']) && check_admin_referer('rsb_game')){ RSB_Jogos::create(['bolao_id'=>$bid]+$_POST); echo '<div class="notice notice-success"><p>Jogo adicionado.</p></div>'; } if(isset($_POST['rsb_update_game']) && check_admin_referer('rsb_update_game')){ RSB_Jogos::update((int)$_POST['jogo_id'], $_POST); echo '<div class="notice notice-success"><p>Jogo atualizado.</p></div>'; } $items=RSB_Jogos::all($bid); ?>
<div class="wrap rsb-wrap"><h1>Jogos Oficiais</h1>
<p><a class="button button-primary" href="<?php echo esc_url(admin_url('admin.php?page=rsb-importar-copa')); ?>">Importar Copa 2026</a></p>
<form method="post" class="rsb-inline rsb-inline-wide"><?php wp_nonce_field('rsb_game'); ?><input name="codigo_jogo" placeholder="Código" required><input name="rodada" placeholder="Rodada/Fase"><input name="grupo" placeholder="Grupo"><input type="date" name="data_jogo"><input type="time" name="hora_jogo"><input name="local_jogo" placeholder="Cidade/Estádio"><input name="time_mandante" placeholder="Time 1" required><input name="time_visitante" placeholder="Time 2" required><button class="button button-primary" name="rsb_add_game" value="1">Adicionar</button></form>
